public class EventOrderLogTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void fire(java.awt.Container panel, String name) {
        java.awt.Component c = find(panel, name);
        if (c instanceof javax.swing.AbstractButton) {
            ((javax.swing.AbstractButton) c).doClick();
        }
    }

    public static void main(String[] args) {
        try {
            EventOrderLog panel = new EventOrderLog();
            check("history starts empty", "", panel.history());
            check("log starts empty", 0, panel.log().size());

            fire(panel, "save");
            check("after one save click", "save#1", panel.history());

            fire(panel, "save");
            check("the same source keeps counting", "save#1,save#2", panel.history());

            fire(panel, "debug");
            fire(panel, "load");
            fire(panel, "debug");
            check("order across components",
                    "save#1,save#2,debug#1,load#1,debug#2", panel.history());

            check("timesFired for save", 2, panel.timesFired("save"));
            check("timesFired for debug", 2, panel.timesFired("debug"));
            check("timesFired for load", 1, panel.timesFired("load"));
            check("timesFired for an unknown name", 0, panel.timesFired("quit"));
            check("log size", 5, panel.log().size());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

