import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JPanel;

public class EventOrderLog extends JPanel implements ActionListener {

    private final JButton save = new JButton("Save");
    private final JButton load = new JButton("Load");
    private final JCheckBox debug = new JCheckBox("Debug");
    private final List<String> log = new ArrayList<>();
    private final Map<String, Integer> counts = new HashMap<>();

    public EventOrderLog() {
        save.setName("save");
        load.setName("load");
        debug.setName("debug");
        add(save);
        add(load);
        add(debug);
        save.addActionListener(this);
        load.addActionListener(this);
        debug.addActionListener(this);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        java.awt.Component source = (java.awt.Component) e.getSource();
        String name = source.getName();
        int soFar = timesFired(name) + 1;
        counts.put(name, soFar);
        log.add(name + "#" + soFar);
    }

    public int timesFired(String name) {
        Integer value = counts.get(name);
        return value == null ? 0 : value;
    }

    public List<String> log() {
        return new ArrayList<>(log);
    }

    public String history() {
        return String.join(",", log);
    }
}
